<template>
  <footer
    class="site-footer d-flex flex-wrap align-items-center justify-content-between gap-3 py-4 border-top border-line"
  >
    <span>{{ config.fullName }} · {{ config.titleBar }}</span>
    <span v-if="status === 'ready'" class="d-inline-flex align-items-center gap-2">
      <button type="button" class="key-button" @click="openModal">SSH public key</button>
      <button
        type="button"
        class="key-button"
        :aria-label="copied ? 'Copied' : 'Copy SSH public key'"
        :title="copied ? 'Copied' : 'Copy SSH public key'"
        @click="copyKey"
      >
        <i class="bi" :class="copied ? 'bi-check2' : 'bi-files'" aria-hidden="true"></i>
      </button>
      <span v-if="copied" role="status">Copied</span>
    </span>
    <span v-else-if="status === 'loading'">Loading SSH public key…</span>
    <span v-else>SSH public key unavailable</span>
  </footer>

  <Teleport v-if="!isPrerendering" to="body">
    <div ref="modal" class="modal fade" tabindex="-1" aria-labelledby="ssh-key-title" aria-hidden="true">
      <div class="modal-dialog modal-dialog-centered modal-lg modal-dialog-scrollable">
        <div class="modal-content">
          <div class="modal-header">
            <h2 id="ssh-key-title" class="modal-title">SSH public key</h2>
            <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button>
          </div>
          <div class="modal-body">
            <pre v-for="key in keys" :key="key" class="ssh-key"><code>{{ key }}</code></pre>
          </div>
          <div class="modal-footer">
            <button type="button" class="btn btn-sm btn-outline-secondary" @click="copyKey">
              <i class="bi" :class="copied ? 'bi-check2' : 'bi-files'" aria-hidden="true"></i>
              {{ copied ? 'Copied' : 'Copy' }}
            </button>
          </div>
        </div>
      </div>
    </div>
  </Teleport>
</template>

<script>
import Modal from 'bootstrap/js/dist/modal'

export default {
  name: 'FooterSection',
  props: {
    config: Object
  },
  data() {
    return {
      keys: [],
      status: 'loading',
      copied: false,
      copyTimer: null,
      isPrerendering: Boolean(window.__PRERENDER_INJECTED?.prerendering)
    }
  },
  computed: {
    keyText() {
      return this.keys.join('\n')
    }
  },
  methods: {
    async loadKeys() {
      try {
        const user = encodeURIComponent(this.config.githubUsername)
        const { data } = await this.axios.get(`https://api.github.com/users/${user}/keys`)
        this.keys = data.map((item) => item.key).filter(Boolean)
        this.status = this.keys.length ? 'ready' : 'empty'
      } catch {
        this.status = 'error'
      }
    },
    openModal() {
      Modal.getOrCreateInstance(this.$refs.modal).show()
    },
    async copyKey() {
      try {
        await navigator.clipboard.writeText(this.keyText)
      } catch {
        // The Clipboard API is missing on insecure origins.
        const area = document.createElement('textarea')
        area.value = this.keyText
        area.style.position = 'fixed'
        document.body.appendChild(area)
        area.select()
        document.execCommand('copy')
        document.body.removeChild(area)
      }
      this.copied = true
      clearTimeout(this.copyTimer)
      this.copyTimer = setTimeout(() => (this.copied = false), 2000)
    }
  },
  mounted() {
    this.loadKeys()
  },
  beforeUnmount() {
    clearTimeout(this.copyTimer)
    Modal.getInstance(this.$refs.modal)?.dispose()
  }
}
</script>

