<template>
  <section class="py-5" id="work">
    <div class="d-flex flex-column flex-md-row justify-content-between align-items-md-end gap-2 mb-4">
      <div>
        <div class="eyebrow">From GitHub</div>
        <h2 class="mb-0">Latest contributions</h2>
      </div>
      <a class="muted small" :href="githubUrl" target="_blank" rel="noopener noreferrer">
        All repositories <i class="bi bi-arrow-up-right" aria-hidden="true"></i>
      </a>
    </div>

    <div class="row g-3">
      <p v-if="status === 'loading'" class="muted col-12">Loading latest repositories…</p>
      <p v-else-if="status !== 'ready'" class="muted col-12">
        Repositories are unavailable right now.
        <a :href="githubUrl" target="_blank" rel="noopener noreferrer">View them on GitHub</a>.
      </p>
      <div v-for="project in featured" :key="project.name" class="col-12 col-md-4">
        <article class="project">
          <header class="project-head">
            <h3>{{ project.name }}</h3>
            <time :datetime="project.pushedAt">{{ project.updated }}</time>
          </header>
          <p v-if="project.description">{{ project.description }}</p>
          <div class="tags">
            <span v-for="tag in project.tags" :key="tag" class="tag">{{ tag }}</span>
          </div>
          <a class="repo-link" :href="project.url" target="_blank" rel="noopener noreferrer">
            Explore repository <i class="bi bi-arrow-up-right" aria-hidden="true"></i>
          </a>
        </article>
      </div>
    </div>

    <ul v-if="rest.length" class="pills">
      <li v-for="project in rest" :key="project.name">
        <a class="pill" :href="project.url" :title="project.description" target="_blank" rel="noopener noreferrer">
          <span class="pill-name">{{ project.name }}</span>
          <time :datetime="project.pushedAt">{{ project.updated }}</time>
        </a>
      </li>
    </ul>
  </section>
</template>


<script>
const MAX_PROJECTS = 12
const FEATURED_COUNT = 3

export default {
  name: 'BodySectionGitHub',
  props: {
    config: Object
  },
  computed: {
    githubUrl() {
      return `https://github.com/${this.config.githubUsername}`
    },
    featured() {
      return this.projects.slice(0, FEATURED_COUNT)
    },
    rest() {
      return this.projects.slice(FEATURED_COUNT)
    }
  },
  data() {
    return {
      projects: [],
      status: 'loading'
    }
  },
  methods: {
    normalizeDescription(description) {
      const value = (description || '').trim()
      return value === 'No description provided.' ? '' : value
    },
    async loadProjects() {
      try {
        const user = encodeURIComponent(this.config.githubUsername)
        const { data } = await this.axios.get(`https://api.github.com/users/${user}/repos`, {
          params: { sort: 'pushed', direction: 'desc', per_page: MAX_PROJECTS }
        })
        this.projects = data.map((repo) => ({
          name: repo.name,
          url: repo.html_url,
          description: this.normalizeDescription(repo.description),
          pushedAt: repo.pushed_at,
          updated: new Date(repo.pushed_at).toLocaleDateString('en', { month: 'short', year: 'numeric' }),
          tags: [repo.language, ...repo.topics.slice(0, 3)].filter(Boolean)
        }))
        this.status = this.projects.length ? 'ready' : 'empty'
      } catch {
        this.status = 'error'
      }
    }
  },
  mounted() {
    this.loadProjects()
  }
}

</script>

