<template>
  <header class="d-flex flex-wrap align-items-center justify-content-between gap-3 py-4 border-bottom border-line">
    <a class="brand" href="#home">Sarbanha<span>.Dev</span></a>
    <nav class="d-flex align-items-center gap-3 gap-md-4" aria-label="Main navigation">
      <a class="site-nav-link" href="#work">Contributions</a>
      <a class="site-nav-link" href="#expertise">Expertise</a>
      <a class="site-nav-link" href="#contact">Contact</a>
      <div class="btn-group theme-switch" role="group" aria-label="Colour theme">
        <button
          v-for="choice in themeChoices"
          :key="choice.name"
          type="button"
          class="btn"
          :class="{ active: !isPrerendering && theme === choice.name }"
          :aria-pressed="isPrerendering ? null : String(theme === choice.name)"
          :data-theme-choice="choice.name"
          @click="chooseTheme(choice.name)"
        >
          <i class="bi" :class="choice.icon" aria-hidden="true"></i> {{ choice.label }}
        </button>
      </div>
    </nav>
  </header>
</template>

<script>
const THEME_KEY = 'theme'
const DARK_SCHEME = '(prefers-color-scheme: dark)'
const isTheme = (value) => value === 'light' || value === 'dark'

// localStorage throws when storage is blocked.
const readStoredTheme = () => {
  try {
    const theme = localStorage.getItem(THEME_KEY)
    return isTheme(theme) ? theme : null
  } catch {
    return null
  }
}

export default {
  name: 'HeadingSection',
  data() {
    const scheme = typeof window.matchMedia === 'function'
      ? window.matchMedia(DARK_SCHEME)
      : {
          matches: false,
          addEventListener() {},
          removeEventListener() {}
        }
    const appliedTheme = document.documentElement.getAttribute('data-bs-theme')
    return {
      scheme,
      theme: isTheme(appliedTheme) ? appliedTheme : (scheme.matches ? 'dark' : 'light'),
      isPrerendering: Boolean(window.__PRERENDER_INJECTED?.prerendering),
      themeChoices: [
        { name: 'dark', label: 'Dark', icon: 'bi-moon-stars' },
        { name: 'light', label: 'Light', icon: 'bi-sun' }
      ]
    }
  },
  watch: {
    theme: {
      immediate: true,
      handler(theme) {
        if (!this.isPrerendering) this.applyTheme(theme)
      }
    }
  },
  methods: {
    applyTheme(theme) {
      document.documentElement.setAttribute('data-bs-theme', theme)
      document.documentElement.style.colorScheme = theme
    },
    chooseTheme(name) {
      try {
        localStorage.setItem(THEME_KEY, name)
      } catch {
        // The choice then lasts for this visit only.
      }
      this.theme = name
    },
    followSystemTheme() {
      if (!readStoredTheme()) {
        this.theme = this.scheme.matches ? 'dark' : 'light'
      }
    }
  },
  mounted() {
    this.scheme.addEventListener('change', this.followSystemTheme)
  },
  beforeUnmount() {
    this.scheme.removeEventListener('change', this.followSystemTheme)
  }
}
</script>

