<template>
  <section
    class="bg-soft rounded-3 p-4 p-md-5 mb-5 d-flex flex-column flex-md-row justify-content-between align-items-md-center gap-4"
    id="contact"
  >
    <div>
      <div class="eyebrow">Let’s connect</div>
      <h2>Have a system worth improving?</h2>
      <p class="muted small mt-2 mb-0">For engineering conversations and professional enquiries.</p>

      <ul class="contact-list">
        <li v-for="item in contactItems" :key="item.key" :title="item.label">
          <i class="bi" :class="item.icon" aria-hidden="true"></i>
          <a v-if="item.href" :href="item.href" :target="item.external ? '_blank' : null" rel="noopener noreferrer">
            {{ item.value }}
          </a>
          <span v-else>{{ item.value }}</span>
        </li>
      </ul>

      <div class="social">
        <a
          v-for="link in socialLinks"
          :key="link.brand"
          class="social-link"
          :href="link.link"
          :aria-label="link.label"
          :title="link.label"
          target="_blank"
          rel="noopener noreferrer"
        >
          <i class="bi" :class="link.icon" aria-hidden="true"></i>
        </a>
      </div>
    </div>
    <a
      v-if="mailto"
      class="btn btn-main d-inline-flex align-items-center gap-2 flex-shrink-0"
      :href="mailto"
    >
      Email Martin <i class="bi bi-arrow-up-right" aria-hidden="true"></i>
    </a>
  </section>
</template>

<script>
// Brands that have a Bootstrap Icons glyph named `bi-<brand>`; anything else gets a generic link icon.
const SOCIAL_ICONS = new Set([
  'behance', 'discord', 'dribbble', 'facebook', 'github', 'gitlab', 'instagram', 'line', 'linkedin',
  'mastodon', 'medium', 'messenger', 'microsoft-teams', 'pinterest', 'reddit', 'signal', 'skype', 'slack',
  'snapchat', 'spotify', 'stack-overflow', 'steam', 'telegram', 'threads', 'tiktok', 'twitch', 'twitter',
  'twitter-x', 'wechat', 'whatsapp', 'youtube'
])
const SOCIAL_ALIASES = { x: 'twitter-x', teams: 'microsoft-teams' }
const CONTACT_ICONS = {
  email: 'bi-envelope',
  phone: 'bi-telephone',
  tel: 'bi-telephone',
  mobile: 'bi-phone',
  whatsapp: 'bi-whatsapp',
  signal: 'bi-signal',
  telegram: 'bi-telegram',
  messenger: 'bi-messenger',
  line: 'bi-line',
  wechat: 'bi-wechat',
  discord: 'bi-discord',
  slack: 'bi-slack',
  teams: 'bi-microsoft-teams',
  skype: 'bi-skype',
  viber: 'bi-chat-dots',
  threema: 'bi-chat-dots',
  imessage: 'bi-chat-text',
  sms: 'bi-chat-text',
  address: 'bi-geo-alt',
  location: 'bi-geo-alt'
}

const titleCase = (text) => text.replace(/[-_]+/g, ' ').replace(/\b\w/g, (char) => char.toUpperCase())

// Messenger entries hold a phone number or a username; a number is only linked when it looks like one.
function contactHref(name, value) {
  const digits = value.replace(/\D/g, '')
  const isNumber = /^\+?[\d\s().-]+$/.test(value) && digits.length >= 7
  const handle = value.replace(/^@/, '')
  if (/^(https?|[a-z][a-z0-9+.-]*):\/\//i.test(value)) return value
  if (name === 'email' || /^[^@\s]+@[^@\s]+$/.test(value)) return `mailto:${value}`
  if (['phone', 'tel', 'mobile'].includes(name)) return `tel:${value.replace(/[^+\d]/g, '')}`
  if (['sms', 'imessage'].includes(name)) return isNumber ? `sms:+${digits}` : ''
  if (name === 'whatsapp') return isNumber ? `https://wa.me/${digits}` : ''
  if (name === 'signal') return isNumber ? `https://signal.me/#p/+${digits}` : ''
  if (name === 'viber') return isNumber ? `viber://chat?number=%2B${digits}` : ''
  if (name === 'telegram') return isNumber ? `https://t.me/+${digits}` : `https://t.me/${handle}`
  if (name === 'messenger') return `https://m.me/${handle}`
  if (name === 'threema') return `https://threema.id/${handle}`
  if (name === 'line') return `https://line.me/ti/p/~${handle}`
  if (name === 'skype') return `skype:${value}?chat`
  return ''
}

export default {
  name: 'BodySectionContact',
  props: {
    config: Object
  },
  computed: {
    mailto() {
      const email = this.config.contact && this.config.contact.email
      return email ? `mailto:${email}` : ''
    },
    // Every entry in config.contact is shown; the key decides the icon and link type.
    contactItems() {
      return Object.entries(this.config.contact || {})
        .map(([key, raw]) => {
          const name = key.toLowerCase()
          const value = String(raw ?? '').trim()
          const href = contactHref(name, value)
          return {
            key,
            name,
            value,
            href,
            external: href.startsWith('http'),
            label: titleCase(key),
            icon: CONTACT_ICONS[name] || 'bi-info-circle'
          }
        })
        .filter((item) => item.value)
    },
    // Every entry in config.socialLinks is shown; `icon` and `label` are optional overrides.
    socialLinks() {
      return (this.config.socialLinks || []).map((link) => {
        const brand = SOCIAL_ALIASES[link.brand] || String(link.brand || '').toLowerCase()
        return {
          ...link,
          icon: link.icon || (SOCIAL_ICONS.has(brand) ? `bi-${brand}` : 'bi-link-45deg'),
          label: link.label || titleCase(brand)
        }
      })
    }
  }
}
</script>

